events.body:
/* OmniDR report field reference. This commented object is DOCUMENTATION, not data.js.
 * Write data.js with a JSON serializer: window.DATA = <strict JSON>;
 * Renderer inputs contain no functions or executable expressions.
 * Times refer to the original source. Media/evidence paths stay inside the report.
 * Fill fields from observations and saved sources, not the illustrative values here.
 */
window.OMNIDR_SCHEMA_EXAMPLE = {
  meta: { theme: "t05", category: "Subject category", lang: "en" },
  summary: "The source and the externally supported finding [S1].",
  video: { src: "media/source.mp4", title: "Video title", duration: 120, poster: "img/poster.jpg" },
  segments: [
    {
      id: "seg1", start: 0, end: 120, title: "Semantic segment title",
      keyframe: "img/seg1-00m30s.jpg",
      caption: [
        { type: "text", text: "Observed visual and spoken content. External claims cite [S1]." },
        { type: "image", src: "anchors/A1-detail.jpg", cap: "What this source crop shows." },
        { type: "flow", title: "Process", steps: ["Step one", "Step two"] },
        { type: "mindmap", root: "Topic", branches: [{ label: "Branch", items: ["Detail"] }] },
        { type: "svg", svg: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 100 100\"><circle cx=\"50\" cy=\"50\" r=\"20\"/></svg>" }
      ],
      sources: ["S1"],
      insights: [] // Same insight shapes and evidence requirements as the top-level array.
    }
  ],
  anchors: [
    {
      id: "A1", label: "Research question", category: "comparison",
      why: "Why external evidence would help the viewer.", segmentIds: ["seg1"],
      frame: "anchors/A1-detail.jpg" // Optional inspected source crop.
    }
  ],
  // Categories: background, more support, comparison, commentary, related material, timeliness.
  // Chinese equivalents: 背景知识, 更多支撑, 类似产品·事件对比, 网络观点评论, 相似资料, 时效纠偏.
  research: [
    {
      id: "S1", type: "web", title: "Opened source title", url: "https://example.org/article",
      summary: "The finding actually read from this source.", anchorId: "A1",
      publisher: "Independent author or publisher", primary: true,
      media: "_assets/docs/S1.html" // Required saved evidence; thumb is an optional local image.
    },
    {
      id: "S2", type: "video", title: "Watched related video", url: "https://example.org/watch",
      summary: "Finding grounded in inspected visual and audio ranges.", anchorId: "A1",
      publisher: "Independent video creator",
      media: "_assets/videos/S2.mp4", perception: "_work/S2/reading.json"
    }
  ],
  // Source types: web, image, video, report. A PDF uses type report and a local PDF media path.
  insights: [
    {
      kind: "compare", title: "A supported comparison",
      table: { cols: ["Dimension", "Source video", "External evidence"], rows: [["Dimension A", "Value", "Value"]] },
      body: "The comparison and its practical implication [S1][S2].", sources: ["S1", "S2"],
      evidence: [
        { srcId: "S1", quote: "A verbatim passage of at least twenty characters from the saved source.", local: "_assets/docs/S1.html" },
        { srcId: "S2", quote: "A faithful transcript passage supporting the compared statement.", local: "_assets/docs/S2-transcript.txt" }
      ]
    },
    { kind: "cause", title: "Explanation", body: "A source-backed explanation [S1].", sources: ["S1"] },
    { kind: "context", title: "Background", body: "Useful background [S1].", sources: ["S1"] }
  ]
};
/* Timeliness insights use kind: "timeliness", title, videoClaim, currentFact,
 * sources and evidence. Include the as-of date and preserve units. Like compare,
 * they require at least two independently produced sources and saved quoted evidence
 * for EVERY cited source, at both report and segment level. Use faithful text extracts
 * for binary PDFs. Mechanical quote matching does not establish the claim's truth.
 */

/* Delivery also requires _work/research-review.json: full source/video readings,
 * primary-reader notes, inspected used crops, current per-claim reviews and browser
 * checks. See the Skill review reference. A structural pass is not delivery-ready. */

{
    "programs": [

    ],
    "streams": [
        {
            "index": 0,
            "codec_name": "h264",
            "width": 720,
            "height": 360,
            "r_frame_rate": "30/1"
        },
        {
            "index": 1,
            "codec_name": "aac",
            "r_frame_rate": "0/0"
        }
    ],
    "format": {
        "duration": "986.069000",
        "size": "34630401"
    }
}

/* Render window.DATA before link.js binds video and citation events. */
(function () {
  "use strict";

  var DATA = (window.DATA && typeof window.DATA === "object") ? window.DATA : {};
  var STRINGS = pickLang(DATA.meta && DATA.meta.lang);
  function el(tag, cls, txt) {
    var n = document.createElement(tag);
    if (cls) n.className = cls;
    if (txt != null) n.textContent = txt;
    return n;
  }
  function frag() { return document.createDocumentFragment(); }
  function isArr(x) { return Array.isArray(x); }
  function num(x, d) { var n = parseFloat(x); return isFinite(n) ? n : (d || 0); }
  function fmtTime(sec) {
    sec = Math.max(0, Math.floor(num(sec, 0)));
    var h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60), s = sec % 60;
    var mm = (h ? String(m).padStart(2, "0") : String(m));
    return (h ? h + ":" : "") + mm + ":" + String(s).padStart(2, "0");
  }
  function pickLang(lang) {
    var zh = !lang || String(lang).toLowerCase().indexOf("zh") === 0;
    return zh
      ? { analysis: "分析", toc: "时间轴", lede: "视频简介", sources: "参考来源",
          insights: "综合洞察", segMore: "延伸", noData: "（暂无数据）" }
      : { analysis: "Analysis", toc: "Timeline", lede: "Overview", sources: "Sources",
          insights: "Insights", segMore: "More", noData: "(no data)" };
  }
  var research = isArr(DATA.research) ? DATA.research : [];
  var SRC_IDS = {};
  research.forEach(function (r) { if (r && r.id) SRC_IDS[r.id] = true; });
  var brokenCites = {};
  // Parse inline formatting into DOM nodes without interpreting HTML.
  function withCites(text) {
    if (text == null) return frag();
    return renderInline(String(text));
  }
  function renderInline(str) {
    var out = frag(), i = 0, n = str.length, buf = "";
    function flush() { if (buf) { out.appendChild(document.createTextNode(buf)); buf = ""; } }
    while (i < n) {
      var ch = str.charAt(i);
      if (ch === "[") {
        var mc = /^\[(S\d+)\]/.exec(str.slice(i));
        if (mc) { flush(); out.appendChild(citeNode(mc[1])); i += mc[0].length; continue; }
      }
      if (ch === "`") {
        var ce = str.indexOf("`", i + 1);
        if (ce > i + 1) { flush(); out.appendChild(el("code", null, str.slice(i + 1, ce))); i = ce + 1; continue; }
      }
      if (ch === "*" && str.charAt(i + 1) === "*") {
        var be = str.indexOf("**", i + 2);
        if (be > i + 1) {
          flush();
          var strong = el("strong"); strong.appendChild(renderInline(str.slice(i + 2, be)));
          out.appendChild(strong); i = be + 2; continue;
        }
      }
      if (ch === "*" || ch === "_") {
        var isU = ch === "_";
        var openOk = !isU || i === 0 || !/\w/.test(str.charAt(i - 1));
        if (openOk) {
          var ie = str.indexOf(ch, i + 1);
          if (ie > i + 1 && str.charAt(i + 1) !== " " && str.charAt(ie - 1) !== " " &&
              (!isU || ie + 1 >= n || !/\w/.test(str.charAt(ie + 1)))) {
            flush();
            var em = el("em"); em.appendChild(renderInline(str.slice(i + 1, ie)));
            out.appendChild(em); i = ie + 1; continue;
          }
        }
      }
      buf += ch; i++;
    }
    flush();
    return out;
  }
  function citeNode(sid) {
    if (SRC_IDS[sid]) {
      var sup = el("sup", "cite");
      sup.dataset.src = sid;
      sup.textContent = sid.replace(/^S/, "");
      return sup;
    }
    brokenCites[sid] = true;
    var bad = el("span", "cite-broken", sid);
    bad.title = STRINGS.noData;
    return bad;
  }
  function citeList(ids) {
    var span = el("span", "cite-list");
    (isArr(ids) ? ids : []).forEach(function (sid) { span.appendChild(citeNode(sid)); });
    return span;
  }
  function paraInto(parent, text, cls) {
    var p = el("p", cls || null);
    p.appendChild(withCites(text));
    parent.appendChild(p);
    return p;
  }
  // Deduplicate images unless explicitly marked wide.
  var _seenMedia = Object.create(null);
  function mediaFigure(src, cap, wide) {
    if (src && !wide) {
      if (_seenMedia[src]) return null;
      _seenMedia[src] = true;
    }
    var fig = el("figure", "media" + (wide ? " wide" : ""));
    var img = el("img");
    img.src = src;
    img.loading = "lazy";
    img.alt = cap || "";
    img.addEventListener("click", function () { openLightbox(src, cap); });
    img.addEventListener("error", function () {
      fig.classList.add("media-broken");
      if (img.parentNode) img.parentNode.removeChild(img);
      if (!fig.querySelector(".media-missing"))
        fig.insertBefore(el("div", "media-missing", cap ? "图片缺失：" + cap : "图片缺失"), fig.firstChild);
    });
    fig.appendChild(img);
    if (cap) {
      var caption = el("figcaption");
      caption.appendChild(withCites(cap)); fig.appendChild(caption);
    }
    return fig;
  }
  function captionBlock(b) {
    if (!b || typeof b !== "object") return null;
    switch (b.type) {
      case "text":
        if (!b.text) return null;
        var p = el("p"); p.appendChild(withCites(b.text)); return p;
      case "image":
        if (!b.src) return null;
        return mediaFigure(b.src, b.cap, b.wide);
      case "flow":
        return flowBlock(b);
      case "mindmap":
        return mindmapBlock(b);
      case "svg":
        if (!b.svg) return null;
        var w = el("div", "svg-block"), diagram = el("img");
        // Render SVG as an inert image, outside the document DOM.
        diagram.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(String(b.svg));
        diagram.alt = b.title || "Diagram";
        w.appendChild(diagram); return w;
      default:
        if (b.text) { var d = el("p"); d.appendChild(withCites(b.text)); return d; }
        return null;
    }
  }
  function flowBlock(b) {
    var steps = isArr(b.steps) ? b.steps.filter(Boolean) : [];
    if (!steps.length) return null;
    var wrap = el("div", "flow");
    if (b.title) {
      var title = el("div", "flow-title");
      title.appendChild(withCites(b.title)); wrap.appendChild(title);
    }
    steps.forEach(function (s, i) {
      if (i) wrap.appendChild(el("span", "arrow", "→"));
      var step = el("span", "step");
      step.appendChild(withCites(s)); wrap.appendChild(step);
    });
    return wrap;
  }
  function mindmapBlock(b) {
    var branches = isArr(b.branches) ? b.branches : [];
    if (!b.root && !branches.length) return null;
    var wrap = el("div", "mindmap");
    if (b.root) {
      var root = el("div", "mm-root");
      root.appendChild(withCites(b.root)); wrap.appendChild(root);
    }
    var grid = el("div", "mm-branches");
    branches.forEach(function (br) {
      if (!br) return;
      var box = el("div", "mm-branch");
      var label = el("div", "mm-label");
      label.appendChild(withCites(br.label != null ? br.label : (br.title != null ? br.title : "")));
      box.appendChild(label);
      var items = isArr(br.items) ? br.items : (isArr(br.children) ? br.children : []);
      if (items.length) {
        var ul = el("ul");
        items.forEach(function (it) {
          var item = el("li"); item.appendChild(withCites(it)); ul.appendChild(item);
        });
        box.appendChild(ul);
      }
      grid.appendChild(box);
    });
    wrap.appendChild(grid);
    return wrap;
  }
  function insightCard(ins) {
    if (!ins || typeof ins !== "object") return null;
    var kind = ins.kind || "context";
    var card;
    if (ins.title) {
      card = el("details", "insight");
      card.open = true;
      var head = el("summary", "insight-head");
      head.appendChild(el("span", "kind", kind));
      head.appendChild(el("h3", null, ins.title));
      card.appendChild(head);
    } else {
      card = el("div", "insight");
    }
    card.dataset.kind = kind;
    if (kind === "timeliness" && (ins.videoClaim || ins.currentFact)) {
      var grid = el("div", "tl-grid");
      var then = el("div", "cell then");
      then.appendChild(el("div", "lbl", zhOr("视频原述", "In the video")));
      var tp = el("div"); tp.appendChild(withCites(ins.videoClaim || "")); then.appendChild(tp);
      var now = el("div", "cell now");
      now.appendChild(el("div", "lbl", zhOr("最新事实", "As of now")));
      var np = el("div"); np.appendChild(withCites(ins.currentFact || "")); now.appendChild(np);
      grid.appendChild(then); grid.appendChild(now);
      card.appendChild(grid);
    }
    if (ins.body) paraInto(card, ins.body);
    if (ins.table) card.appendChild(tableBlock(ins.table));
    if (isArr(ins.sources) && ins.sources.length) card.appendChild(citeList(ins.sources));
    return card;
  }
  function tableBlock(t) {
    var wrap = el("div", "tbl-wrap");
    var table = el("table");
    if (isArr(t.cols) && t.cols.length) {
      var thead = el("thead"), tr = el("tr");
      t.cols.forEach(function (c) { tr.appendChild(el("th", null, String(c))); });
      thead.appendChild(tr); table.appendChild(thead);
    }
    var tbody = el("tbody");
    (isArr(t.rows) ? t.rows : []).forEach(function (row) {
      var tr = el("tr");
      (isArr(row) ? row : [row]).forEach(function (cell) {
        var td = el("td"); td.appendChild(withCites(String(cell))); tr.appendChild(td);
      });
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    wrap.appendChild(table);
    return wrap;
  }
  function zhOr(zh, en) {
    var isZh = !(DATA.meta && DATA.meta.lang) ||
      String(DATA.meta.lang).toLowerCase().indexOf("zh") === 0;
    return isZh ? zh : en;
  }
  function segmentCard(seg, idx) {
    var card = el("article", "seg");
    var id = seg.id || ("seg" + (idx + 1));
    card.id = "seg-" + id;
    card.dataset.seg = id;
    card.dataset.segStart = num(seg.start, 0);
    var det = el("details", "seg-details");
    det.open = true;
    var head = el("summary", "seg-head");
    head.appendChild(el("span", "seg-badge", fmtTime(seg.start)));
    head.appendChild(el("h3", null, seg.title || (STRINGS.analysis + " " + (idx + 1))));
    det.appendChild(head);

    var body = el("div", "seg-body");
    if (seg.keyframe) {
      var kf = mediaFigure(seg.keyframe, seg.title || "", false);
      if (kf) body.appendChild(kf);
    }
    var caption = isArr(seg.caption) ? seg.caption : (seg.text ? [{ type: "text", text: seg.text }] : []);
    caption.forEach(function (b) {
      var node = captionBlock(b);
      if (node) body.appendChild(node);
    });
    if (isArr(seg.sources) && seg.sources.length) body.appendChild(citeList(seg.sources));
    var segIns = isArr(seg.insights) ? seg.insights : [];
    if (segIns.length) {
      var box = el("div", "insights");
      box.style.marginTop = "14px";
      segIns.forEach(function (ins) {
        var n = insightCard(ins);
        if (n) box.appendChild(n);
      });
      body.appendChild(box);
    }

    det.appendChild(body);
    card.appendChild(det);
    return card;
  }
  function sourceCard(r) {
    var card = el("div", "src");
    card.id = "src-" + r.id;
    card.appendChild(el("span", "sid", r.id));
    var main = el("div");
    var titleLine = el("div", "stitle");
    if (r.url) {
      var a = el("a", null, r.title || r.url);
      a.href = r.url; a.target = "_blank"; a.rel = "noopener noreferrer";
      titleLine.appendChild(a);
    } else {
      titleLine.appendChild(document.createTextNode(r.title || r.id));
    }
    if (r.type) titleLine.appendChild(el("span", "stype", r.type));
    main.appendChild(titleLine);
    if (r.summary) main.appendChild(el("div", "ssum", r.summary));
    if (r.thumb) {
      var img = el("img", "sthumb"); img.src = r.thumb; img.loading = "lazy"; img.alt = "";
      img.addEventListener("click", function () { openLightbox(r.thumb, r.title); });
      img.addEventListener("error", function () { if (img.parentNode) img.parentNode.removeChild(img); });
      main.appendChild(img);
    }
    card.appendChild(main);
    return card;
  }
  var lightbox;
  function openLightbox(src, cap) {
    if (!lightbox) return;
    var img = lightbox.querySelector("img");
    img.src = src; img.alt = cap || "";
    lightbox.hidden = false;
  }
  function initLightbox() {
    lightbox = el("div", "lightbox");
    lightbox.hidden = true;
    lightbox.appendChild(el("img"));
    lightbox.addEventListener("click", function () { lightbox.hidden = true; });
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && lightbox && !lightbox.hidden) lightbox.hidden = true;
    });
    document.body.appendChild(lightbox);
  }
  // TOC entries omit data-seg-start to avoid duplicate playback listeners.
  function buildTOC(segs, player) {
    var nav = el("nav", "toc");
    var head = el("div", "toc-head");
    head.appendChild(el("span", "toc-head-label", STRINGS.toc));
    var toggleAll = el("button", "toc-toggle-all", zhOr("全部展开/折叠", "Expand/collapse all"));
    toggleAll.type = "button";
    toggleAll.addEventListener("click", function () {
      var ds = document.querySelectorAll("details.seg-details, details.insight");
      var anyOpen = false;
      for (var i = 0; i < ds.length; i++) { if (ds[i].open) { anyOpen = true; break; } }
      for (var k = 0; k < ds.length; k++) { ds[k].open = !anyOpen; }
    });
    head.appendChild(toggleAll);
    nav.appendChild(head);

    segs.forEach(function (seg, idx) {
      var id = seg.id || ("seg" + (idx + 1));
      var item = el("button", "toc-item");
      item.type = "button";
      item.dataset.tocSeg = id;
      item.appendChild(el("span", "toc-time", fmtTime(seg.start)));
      item.appendChild(el("span", "toc-title", seg.title || (STRINGS.analysis + " " + (idx + 1))));
      item.addEventListener("click", function () {
        var t = num(seg.start, 0);
        if (player) {
          try { player.currentTime = t; } catch (e) {}
          var p = player.play && player.play();
          if (p && p.catch) p.catch(function () {});
        }
        var target = document.getElementById("seg-" + id);
        if (target) {
          var d = target.querySelector ? target.querySelector("details") : null;
          if (d && !d.open) d.open = true;
          target.scrollIntoView({ behavior: "smooth", block: "start" });
        }
      });
      nav.appendChild(item);
    });
    function addAnchor(secId, label) {
      var item = el("button", "toc-item toc-anchor");
      item.type = "button";
      item.appendChild(el("span", "toc-title", label));
      item.addEventListener("click", function () {
        var t = document.getElementById(secId);
        if (t) t.scrollIntoView({ behavior: "smooth", block: "start" });
      });
      nav.appendChild(item);
    }
    if (isArr(DATA.insights) && DATA.insights.length) addAnchor("sec-insights", STRINGS.insights);
    if (research.length) addAnchor("sec-sources", STRINGS.sources);
    if (player) {
      player.addEventListener("timeupdate", function () {
        syncTOC(nav, segs, player.currentTime);
      });
    }
    return nav;
  }
  function syncTOC(nav, segs, t) {
    var active = 0;
    for (var i = 0; i < segs.length; i++) {
      if (num(segs[i].start, 0) <= t + 1e-3) active = i; else break;
    }
    var items = nav.querySelectorAll(".toc-item:not(.toc-anchor)");
    for (var j = 0; j < items.length; j++) {
      items[j].classList.toggle("is-active", j === active);
    }
  }
  function render() {
    _seenMedia = Object.create(null);
    var root = document.documentElement;
    var theme = (DATA.meta && DATA.meta.theme) || "t01";
    if (!/^t(0[1-9]|1[0-9]|20)$/.test(theme)) theme = "t01";
    root.dataset.theme = theme;
    if (DATA.meta && DATA.meta.lang) root.lang = DATA.meta.lang;
    else if (!root.lang) root.lang = "zh";
    var bg = DATA.meta && DATA.meta.background;
    if (bg && typeof bg === "string") {
      root.style.setProperty("--bg-image", 'url("' + bg.replace(/["\\]/g, encodeURIComponent) + '")');
      root.setAttribute("data-has-bg", "1");
    } else {
      root.style.removeProperty("--bg-image");
      root.removeAttribute("data-has-bg");
    }

    var app = document.getElementById("app");
    if (!app) { app = el("div", "app"); document.body.appendChild(app); }
    app.innerHTML = "";

    var video = DATA.video || {};
    var segs = isArr(DATA.segments) ? DATA.segments.slice() : [];
    segs.sort(function (a, b) { return num(a.start, 0) - num(b.start, 0); });
    var left = el("aside", "left");
    var pw = el("div", "player-wrap");
    var v = document.createElement("video");
    v.id = "player";
    v.controls = true;
    v.preload = "metadata";
    v.playsInline = true;
    if (video.poster) v.poster = video.poster;
    var source = document.createElement("source");
    source.src = video.src || "media/source.mp4";
    v.appendChild(source);
    pw.appendChild(v);
    left.appendChild(pw);
    left.appendChild(buildTOC(segs, v));
    app.appendChild(left);
    var right = el("main", "right");

    var hero = el("header", "hero");
    if (DATA.meta && DATA.meta.category) hero.appendChild(el("div", "kicker", DATA.meta.category));
    hero.appendChild(el("h1", null, video.title || "Omni Deep Research"));
    var lede = DATA.summary || (DATA.meta && DATA.meta.summary);
    if (lede) {
      var det = el("details", "hero-lede");
      det.appendChild(el("summary", null, STRINGS.lede));
      var lb = el("div", "lede-body");
      lb.appendChild(withCites(String(lede)));
      det.appendChild(lb);
      hero.appendChild(det);
    }
    right.appendChild(hero);
    right.appendChild(sectionTitle(STRINGS.analysis));
    if (segs.length) {
      var segWrap = el("section", "segments");
      segs.forEach(function (seg, i) { segWrap.appendChild(segmentCard(seg, i)); });
      right.appendChild(segWrap);
    } else {
      right.appendChild(el("p", "notice", STRINGS.noData));
    }
    var xins = isArr(DATA.insights) ? DATA.insights : [];
    if (xins.length) {
      right.appendChild(sectionTitle(STRINGS.insights, "sec-insights"));
      var ibox = el("section", "insights");
      xins.forEach(function (ins) { var n = insightCard(ins); if (n) ibox.appendChild(n); });
      right.appendChild(ibox);
    }
    if (research.length) {
      right.appendChild(sectionTitle(STRINGS.sources, "sec-sources"));
      var sbox = el("section", "sources");
      research.forEach(function (r) { if (r && r.id) sbox.appendChild(sourceCard(r)); });
      right.appendChild(sbox);
    }

    right.appendChild(footer(video));
    app.appendChild(right);

    initLightbox();
    var broken = Object.keys(brokenCites);
    if (broken.length) {
      console.warn("[video-report-ui] " + broken.length +
        " citation(s) reference a missing research source: " + broken.join(", ") +
        ". They render inert. Add them to window.DATA.research or remove the [S#] marker.");
    }
    return { segments: segs.length, sources: research.length, broken: broken };
  }
  function sectionTitle(t, id) {
    var h = el("h2", "sec-title", t);
    if (id) h.id = id;
    return h;
  }
  function footer(video) {
    var f = el("footer", "footer");
    var bits = [];
    if (video.duration) bits.push(zhOr("时长", "Duration") + " " + fmtTime(video.duration));
    bits.push(zhOr("由 Omni Deep Research 生成", "Generated by Omni Deep Research"));
    f.textContent = bits.join(" · ");
    return f;
  }
  // link.js needs the segment DOM immediately, before DOMContentLoaded.
  window.__renderReport = render;
  render();
})();

#!/usr/bin/env node
/* Validate the OmniDR report data, citations, local media, and saved evidence. */
import fs from "node:fs";
import nodePath from "node:path";

const ANCHOR_CATS = new Set([
  "背景知识", "更多支撑", "类似产品·事件对比", "网络观点评论", "相似资料", "时效纠偏",
  "background", "more support", "comparison", "commentary", "related material", "timeliness",
]);
const RESEARCH_TYPES = new Set(["web", "image", "video", "report"]);
const BLOCK_TYPES = new Set(["text", "image", "flow", "mindmap", "svg"]);
const KNOWN_KINDS = new Set(["timeliness", "compare", "cause", "context"]);

const errors = [];
const warns = [];
const E = (m) => errors.push(m);
const W = (m) => warns.push(m);

function isNum(x) { return typeof x === "number" && isFinite(x); }
function isStr(x) { return typeof x === "string" && x.length > 0; }
function isArr(x) { return Array.isArray(x); }

const path = process.argv[2];
if (!path) { console.error("usage: node validate_data.mjs <js/data.js>"); process.exit(2); }
let code;
try { code = fs.readFileSync(path, "utf8"); }
catch (e) { console.error(`cannot read ${path}: ${e.message}`); process.exit(2); }

const dataDir = nodePath.dirname(nodePath.resolve(path));
const reportRoot = nodePath.basename(dataDir) === "js" ? nodePath.dirname(dataDir) : dataDir;

const localAssets = new Map(); // rel-path -> [where,...]
function isRemoteAsset(p) { return /^(https?:)?\/\//i.test(p) || /^(oss|data|blob):/i.test(p); }
function noteAsset(p, where) {
  if (!isStr(p) || isRemoteAsset(p)) return;   // only local, in-report paths are checked
  if (!localAssets.has(p)) localAssets.set(p, []);
  localAssets.get(p).push(where);
}

let DATA;
try {
  const match = code.trim().match(/^window\.DATA\s*=\s*([\s\S]*?);?$/);
  if (!match) throw new Error("expected window.DATA = <JSON>;");
  DATA = JSON.parse(match[1]);
} catch {
  console.error("data.js must contain only window.DATA = <JSON>; (no executable JavaScript)");
  process.exit(1);
}

if (!DATA || typeof DATA !== "object") {
  console.error("✗ window.DATA is missing or not an object.");
  process.exit(1);
}

const research = isArr(DATA.research) ? DATA.research : [];
const SRC_IDS = new Set();
const SRC_MEDIA = new Map();   // S# -> local copy path ("" when the page was never saved)
research.forEach((r) => {
  if (!r || !isStr(r.id)) return;
  SRC_IDS.add(r.id);
  SRC_MEDIA.set(r.id, isStr(r.media) ? r.media : "");
});

const allInsights = [];       // {ins, at} — the evidence pass needs research[] parsed first
const referenced = new Map(); // id -> where (for error messages)
function refCite(id, where) { if (!referenced.has(id)) referenced.set(id, where); }
function scanText(text, where) {
  if (text == null) return;
  const re = /\[(S\d+)\]/g; let m;
  while ((m = re.exec(String(text))) !== null) refCite(m[1], where);
}
function scanSources(arr, where) {
  (isArr(arr) ? arr : []).forEach((id) => { if (isStr(id)) refCite(id, where); });
}

if (DATA.meta) {
  const t = DATA.meta.theme;
  if (t != null && !/^t(0[1-9]|1[0-9]|20)$/.test(String(t)))
    E(`meta.theme "${t}" is not t01..t20.`);
  const bg = DATA.meta.background;
  if (bg != null) {
    if (typeof bg !== "string" || !bg.length) E("meta.background must be a non-empty string path (or omit it).");
    else {
      if (/^(https?:)?\/\//i.test(bg)) W(`meta.background "${bg}" is a remote URL — download it into img/bg/ so file:// stays offline.`);
      else { if (!/^img\//.test(bg)) W(`meta.background "${bg}" should live under img/ (e.g. img/bg/hero.jpg) so it travels with the report.`); noteAsset(bg, "meta.background"); }
    }
  }
}
const video = DATA.video || {};
if (!isStr(video.title)) W("video.title is empty.");
if (!isNum(video.duration)) E("video.duration must be a number (seconds).");
else if (video.duration <= 0) W("video.duration is 0 — set it from omnidr_media_info.");
noteAsset(video.src, "video.src");
noteAsset(video.poster, "video.poster");
if (!isStr(video.poster))
  W("video.poster is empty — the left pane shows a black box until playback starts. " +
    "Extract one frame with omnidr_extract_frame into img/ and point poster at it.");

scanText(DATA.summary, "summary");

const frameUses = new Map(); // src -> [where,...]  (right-column figures only)
function noteFrame(src, where) {
  if (!isStr(src)) return;
  if (!frameUses.has(src)) frameUses.set(src, []);
  frameUses.get(src).push(where);
}
function tsOf(src) { // best-effort seconds from names like seg3-02m35s.jpg
  const m = /(\d+)m(\d+)s/.exec(String(src || ""));
  return m ? parseInt(m[1], 10) * 60 + parseInt(m[2], 10) : null;
}

const segs = isArr(DATA.segments) ? DATA.segments : [];
if (!segs.length) E("segments[] is empty — the report has no backbone.");
const segIds = new Set();
segs.forEach((s, i) => {
  const at = `segments[${i}]`;
  if (!s || typeof s !== "object") { E(`${at} is not an object.`); return; }
  if (!isStr(s.id)) E(`${at}.id missing.`);
  else { if (segIds.has(s.id)) E(`${at}.id "${s.id}" is duplicated.`); segIds.add(s.id); }
  if (!isNum(s.start)) E(`${at}.start must be a number.`);
  if (!isNum(s.end)) E(`${at}.end must be a number.`);
  if (isNum(s.start) && isNum(s.end) && !(s.start < s.end))
    E(`${at}: need start < end (got ${s.start} … ${s.end}).`);
  if (!isStr(s.title)) W(`${at}.title is empty.`);
  if (s.keyframe != null) {
    if (!/^img\//.test(String(s.keyframe))) W(`${at}.keyframe "${s.keyframe}" should live under img/.`);
    noteFrame(s.keyframe, `${at}.keyframe`);
    noteAsset(s.keyframe, `${at}.keyframe`);
  }
  const caption = isArr(s.caption) ? s.caption : [];
  caption.forEach((b, j) => {
    const bat = `${at}.caption[${j}]`;
    if (!b || typeof b !== "object") { E(`${bat} is not an object.`); return; }
    if (!BLOCK_TYPES.has(b.type)) { E(`${bat}.type "${b.type}" invalid (text|image|flow|mindmap|svg).`); return; }
    if (b.type === "text") { if (!isStr(b.text)) E(`${bat} text block needs .text.`); else scanText(b.text, bat); }
    if (b.type === "image") { if (!isStr(b.src)) E(`${bat} image block needs .src.`); else { noteFrame(b.src, bat); noteAsset(b.src, bat); } if (b.cap) scanText(b.cap, bat); }
    if (b.type === "flow") {
      if (!(isArr(b.steps) && b.steps.length)) E(`${bat} flow block needs steps[].`);
      scanText(b.title, `${bat}.title`);
      (isArr(b.steps) ? b.steps : []).forEach((step, k) => scanText(step, `${bat}.steps[${k}]`));
    }
    if (b.type === "mindmap") {
      if (!b.root && !(isArr(b.branches) && b.branches.length)) E(`${bat} mindmap needs root or branches[].`);
      scanText(b.root, `${bat}.root`);
      (isArr(b.branches) ? b.branches : []).forEach((branch, k) => {
        if (!branch) return;
        const branchAt = `${bat}.branches[${k}]`;
        scanText(branch.label != null ? branch.label : branch.title, branchAt);
        const items = isArr(branch.items) ? branch.items : branch.children;
        (isArr(items) ? items : []).forEach((item) => scanText(item, branchAt));
      });
    }
    if (b.type === "svg" && !isStr(b.svg)) E(`${bat} svg block needs .svg markup.`);
  });
  scanSources(s.sources, `${at}.sources`);
  (isArr(s.insights) ? s.insights : []).forEach((ins, k) => scanInsight(ins, `${at}.insights[${k}]`));
});

const anchors = isArr(DATA.anchors) ? DATA.anchors : [];
const ANCHOR_IDS = new Set();
if (!anchors.length)
  E("anchors[] is missing or empty — record the anchors you researched (§3: id/label/category/why/segmentIds). " +
    "They are the anchor↔evidence trace, not page content; research[].anchorId points at them.");
anchors.forEach((a, i) => {
  const at = `anchors[${i}]`;
  if (!a || typeof a !== "object") { E(`${at} is not an object.`); return; }
  if (!isStr(a.id)) E(`${at}.id missing.`);
  else { if (ANCHOR_IDS.has(a.id)) E(`${at}.id "${a.id}" is duplicated.`); ANCHOR_IDS.add(a.id); }
  if (!isStr(a.label)) W(`${at}.label is empty.`);
  if (a.category != null && !ANCHOR_CATS.has(a.category))
    E(`${at}.category "${a.category}" not in the allowed set.`);
  if (a.frame) { noteFrame(a.frame, `${at}.frame`); noteAsset(a.frame, `${at}.frame`); }   // anchor frames aren't right-column, tracked for dup ts only
});

function scanInsight(ins, at) {
  if (!ins || typeof ins !== "object") { E(`${at} is not an object.`); return; }
  if (ins.kind != null && !KNOWN_KINDS.has(ins.kind))
    E(`${at}.kind "${ins.kind}" invalid (timeliness|compare|cause|context).`);
  allInsights.push({ ins, at });
  scanText(ins.body, `${at}.body`);
  scanText(ins.videoClaim, `${at}.videoClaim`);
  scanText(ins.currentFact, `${at}.currentFact`);
  if (ins.table && isArr(ins.table.rows))
    ins.table.rows.forEach((row) => (isArr(row) ? row : [row]).forEach((c) => scanText(c, `${at}.table`)));
  scanSources(ins.sources, `${at}.sources`);
}
(isArr(DATA.insights) ? DATA.insights : []).forEach((ins, i) => scanInsight(ins, `insights[${i}]`));

const MANGLED_DATE_URL = /^https?:\/\/[^/]+\/(?:[^/]+\/)*?\d{4}-\d{2}-\d{2}\//i;
const SEEN_SRC_IDS = new Set();
let anchorRefs = 0;
research.forEach((r, i) => {
  const at = `research[${i}]`;
  if (!r || typeof r !== "object") { E(`${at} is not an object.`); return; }
  if (!isStr(r.id) || !/^S\d+$/.test(r.id)) E(`${at}.id "${r && r.id}" must match S\\d+.`);
  else if (SEEN_SRC_IDS.has(r.id)) E(`${at}.id "${r.id}" is duplicated.`);
  else SEEN_SRC_IDS.add(r.id);
  if (!RESEARCH_TYPES.has(r.type)) E(`${at}.type "${r.type}" invalid (web|image|video|report).`);
  if (r.type === "web" && !isStr(r.url)) E(`${at} (web) needs a url.`);
  if (!isStr(r.summary)) W(`${at}.summary is empty — add the distilled finding.`);
  if (isStr(r.url) && MANGLED_DATE_URL.test(r.url))
    W(`${at}.url "${r.url}" has a /YYYY-MM-DD/ path — news permalinks use /YYYY/MM/DD/. ` +
      `Open it before citing; this shape is a 404 in practice.`);
  if (r.anchorId != null) {
    anchorRefs++;
    if (!ANCHOR_IDS.has(r.anchorId))
      E(`${at}.anchorId "${r.anchorId}" does not exist in anchors[] — ` +
        `add the anchor or drop the back-reference (dangling anchorIds break the anchor→evidence trace).`);
  }
  noteAsset(r.thumb, `${at}.thumb`);
  noteAsset(r.media, `${at}.media`);
});
if (anchors.length && research.length && anchorRefs === 0)
  W(`${anchors.length} anchor(s) but no research entry carries an anchorId — ` +
    `the anchor→evidence link is one-way. Tag each source with the anchor it answers.`);

const RISK_KINDS = new Set(["timeliness", "compare"]);
const EV_HARD = "hard" === "hard";
const EV = (m) => (EV_HARD ? E(m) : W(m));

function visibleText(s) {
  return s
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, " ")
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, " ")
    .replace(/<[^>]+>/g, " ")
    .replace(/&nbsp;/gi, " ").replace(/&amp;/gi, "&").replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'").replace(/&lt;/gi, "<").replace(/&gt;/gi, ">")
    .replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
    .replace(/[‐-―]/g, "-").replace(/ /g, " ")
    .replace(/\s+/g, " ")
    .toLowerCase();
}
function normQuote(s) {
  return String(s)
    .replace(/[‘’]/g, "'").replace(/[“”]/g, '"')
    .replace(/[‐-―]/g, "-").replace(/ /g, " ")
    .replace(/\s+/g, " ").trim().toLowerCase();
}

let riskInsights = 0, riskWithEvidence = 0, quotesChecked = 0;
const noEvidence = [];
for (const { ins, at } of allInsights) {
  if (!RISK_KINDS.has(ins.kind)) continue;
  riskInsights++;
  const src = [...new Set((isArr(ins.sources) ? ins.sources : []).filter(isStr))];

  if (src.length < 2)
    E(`${at} (kind "${ins.kind}") cites ${src.length} source(s) — corrections and ` +
      `comparisons need ≥2 INDEPENDENT sources (data contract). One source asserting ` +
      `something the video does not say is unverifiable by the reader.`);

  const ev = isArr(ins.evidence) ? ins.evidence : [];
  if (!ev.length) { noEvidence.push(at); continue; }
  riskWithEvidence++;
  ev.forEach((e, j) => {
    const eat = `${at}.evidence[${j}]`;
    if (!e || typeof e !== "object") { EV(`${eat} is not an object.`); return; }
    if (!isStr(e.srcId)) EV(`${eat}.srcId missing.`);
    else if (!SRC_IDS.has(e.srcId)) EV(`${eat}.srcId "${e.srcId}" has no research entry.`);
    else if (!(isArr(ins.sources) && ins.sources.includes(e.srcId)))
      EV(`${eat}.srcId "${e.srcId}" is not in ${at}.sources — evidence must back a cited source.`);

    if (!isStr(e.quote)) { EV(`${eat}.quote missing — paste the sentence that carries the claim.`); return; }
    const q = normQuote(e.quote);
    if (q.length < 20) { EV(`${eat}.quote is ${q.length} chars — too short to be evidence (≥20).`); return; }

    if (!isStr(e.local)) {
      EV(`${eat}.local missing — save the cited page into the report ` +
         `(_assets/docs/${e.srcId || "S#"}.html) and point .local at it. ` +
         `A source read only into the context window leaves nothing to re-check.`);
      return;
    }
    const abs = nodePath.resolve(reportRoot, e.local);
    if (!fs.existsSync(abs)) { EV(`${eat}.local "${e.local}" does not exist (expected ${abs}).`); return; }
    let buf;
    try { buf = fs.readFileSync(abs); }
    catch (err) { EV(`${eat}.local "${e.local}" cannot be read: ${err.message}`); return; }
    if (buf.slice(0, 5).toString("latin1") === "%PDF-" || buf.slice(0, 4096).includes(0)) {
      EV(`${eat}.local is binary; save a faithful text extract with omnidr_read_document and point .local at it.`);
      return;
    }
    if (visibleText(buf.toString("utf8")).includes(q)) quotesChecked++;
    else
      EV(`${eat}.quote is NOT present in "${e.local}" — the saved page does not contain ` +
         `the sentence this claim rests on. Re-read the source: either quote it correctly ` +
         `or drop the claim. (This is the exact shape of a fabricated correction.)`);
  });
}
if (noEvidence.length)
  E(`${noEvidence.length}/${riskInsights} correcting/comparing insight(s) carry no evidence[] — ` +
    `unverifiable downstream: ${noEvidence.slice(0, 6).join(", ")}` +
    (noEvidence.length > 6 ? `, +${noEvidence.length - 6} more` : "") +
    `. Add evidence:[{srcId,quote,local}] with the cited page saved into the report.`);
for (const { ins, at } of allInsights) {
  if (!RISK_KINDS.has(ins.kind)) continue;
  const src = (isArr(ins.sources) ? ins.sources : []).filter(isStr).filter((s) => SRC_IDS.has(s));
  if (src.length && !src.some((s) => SRC_MEDIA.get(s)))
    W(`${at} rests on ${src.length} source(s) and NOT ONE was saved into the report ` +
      `(${src.join(", ")} all have empty .media) — nothing here can be re-checked after the run.`);
}

for (const [id, where] of referenced) {
  if (!SRC_IDS.has(id)) E(`broken citation [${id}] at ${where} — no research entry has id "${id}".`);
}

for (const [src, uses] of frameUses) {
  if (uses.length > 1) W(`frame "${src}" is shown ${uses.length}× (${uses.join(", ")}) — the renderer now de-dups it, but consider distinct frames.`);
}
const framed = [...frameUses.keys()].map((s) => ({ s, t: tsOf(s) })).filter((x) => x.t != null).sort((a, b) => a.t - b.t);
for (let i = 1; i < framed.length; i++) {
  if (framed[i].s !== framed[i - 1].s && Math.abs(framed[i].t - framed[i - 1].t) < 2)
    W(`near-duplicate frames <2s apart: "${framed[i - 1].s}" & "${framed[i].s}" — pick one.`);
}

for (const [rel, uses] of localAssets) {
  const abs = nodePath.resolve(reportRoot, rel);
  if (!fs.existsSync(abs))
    E(`missing local asset "${rel}" (used at ${uses.join(", ")}) — expected at ${abs}. ` +
      `Persist the file into the report or fix the path (remote URLs must be downloaded in).`);
}

warns.forEach((w) => console.warn("  ⚠ " + w));
if (errors.length) {
  console.error(`\n✗ ${errors.length} error(s) in ${path}:`);
  errors.forEach((e) => console.error("  ✗ " + e));
  process.exit(1);
}
console.log(`✓ ${path} valid — ${segs.length} segments, ${research.length} sources, ${referenced.size} citations resolved, ` +
  `${anchors.length} anchors (${anchorRefs} back-refs), ${localAssets.size} local asset(s) found, ` +
  `${riskWithEvidence}/${riskInsights} correcting insight(s) evidenced (${quotesChecked} quote(s) verified)` +
  (warns.length ? `, ${warns.length} warning(s)` : ""));
process.exit(0);

