import requests,concurrent.futures,json,re
from pathlib import Path
from bs4 import BeautifulSoup
p=Path('work/search-')
entries=[]
for f in Path('work').glob('search-*.json'):
 d=json.loads(f.read_text('utf-8'))
 for a in d['links']:
  if any(x in a['title'] for x in ['为大场面','中兴手机官网','Trusted','officially launched','脚本之家','屏下摄像手机成了']): entries.append(a)
def go(a):
 u=a['url']; u='https://www.sogou.com'+u if u.startswith('/') else u
 try:
  r=requests.get(u,timeout=(10,20),headers={'User-Agent':'Mozilla/5.0'})
  r.encoding=r.apparent_encoding
  return {'title':a['title'],'status':r.status_code,'url':r.url,'redirect':r.text[:2000] if 'sogou.com/link?' in r.url else ''}
 except Exception as e:return {'title':a['title'],'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=6) as pool:
 for x in pool.map(go,entries):print(json.dumps(x,ensure_ascii=False),flush=True)
'@ | python -u -"

