import requests,concurrent.futures,json
from bs4 import BeautifulSoup
urls=['https://openaccess.thecvf.com/CVPR2022?day=all','https://openaccess.thecvf.com/ICCV2023?day=all','https://openaccess.thecvf.com/CVPR2024?day=all']
def go(u):
 try:
  r=requests.get(u,timeout=(10,20));s=BeautifulSoup(r.text,'html.parser')
  return {'index':u,'papers':[(a.get_text(' ',strip=True),'https://openaccess.thecvf.com'+a['href']) for a in s.select('a[href]') if 'under-display' in a.get_text().lower()]}
 except Exception as e:return {'index':u,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as p:
 for x in p.map(go,urls):print(json.dumps(x,ensure_ascii=False),flush=True)
'@ | python -u -"

